		gameWS.onmessage=function(k){
	
		    var tmpMess=k.data.split("#");
       
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.jxo.ucx!=undefined){
			
			if(gameController.ehm!=parseInt(tmpMess[1])){
				
			gameController.ehm=parseInt(tmpMess[1]);	
			gameController.peh=parseInt(tmpMess[1]);	
			gameController.jxo.ucx.rzp("creditd", "#jqu", [gameController.yil(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
